export function syncCheckboxState(checkbox) {
  assertCheckbox(checkbox);
  const state = checkbox.indeterminate ? 'indeterminate' : checkbox.checked ? 'checked' : 'unchecked';
  checkbox.dataset.state = state;
  return state;
}

